"""Exact-source review for ten B03-C2 third-omission reset-projection pairs."""
from __future__ import annotations
import json
from pathlib import Path
from experiments.ontology_review_recurrent import source_sha

_LEDGER = Path(__file__).with_name("ontology_har_compact_reset_projection_pairs.json")
EXACT_PAIRS = tuple(json.loads(_LEDGER.read_text(encoding="utf-8")))
_BY_PAIR = {(x["parent_sha256"], x["candidate_sha256"]): x for x in EXACT_PAIRS}

def _fingerprint(transitions: int) -> dict[str, str]:
    return {
        "input_units":"fixed 128-step, nine-channel tri-axial human-activity sensor windows", "input_transform":"raw xyz windows provide mean/std/max summaries", "embedding":"depthwise then pointwise temporal Conv1d stages with pooling", "position":"fixed temporal transition order; no positional embedding", "mixing":"separable convolutions, a forward GRU, and one endpoint GRUCell", "routing":"training uses the dense six-logit path; compact deployment omits three reset inputs at exactly %d selected transitions" % transitions, "state":"per-window GRU states and nonpersistent feature/reset-moment buffers only", "feedforward":"dense six-logit classifier and frozen five-relative-logit compact classifier plus compact reset projections", "parameter_construction":"ordinary learned convolution/GRU/classifier parameters; compact deployment modules synchronize from them and remain frozen", "sharing":"training and compact deployment use the same learned encoder parameters through synchronization", "normalization":"BatchNorm after pointwise temporal convolutions", "connectivity":"separable CNN feeds forward GRU and endpoint cell; recurrent and raw summaries feed dense or compact head", "aggregation":"forward recurrent last state, endpoint-cell state, and raw mean/std/max summaries", "output":"six activity logits with compact class-relative deployment readout", "symmetry":"no symmetric reduction", "conditional_compute":"explicit training versus compact deployment route only", "activation":"ReLU temporal blocks and GRU gates", "stochasticity":"dropout during training only", "bottleneck":"fixed compact feature classifier and %d third-omission reset projections" % transitions, "iteration":"finite temporal GRU scan and %d source-bound extra reset transitions" % transitions, "other":"Complete exact-pair proof: source hashes bind all edits; only the third-omission transition count and its dependent fixed buffers, projection bank, selection, synchronization, and dispatch bounds change.", "sensor_representation":"raw xyz, convolutional sensor features, recurrent states, and raw moments", "sensor_fusion":"pointwise mixing after depthwise temporal filtering; raw summaries join at readout", "temporal_operator":"two pooled separable temporal convolution stages, forward GRU, endpoint GRUCell", "directionality":"forward sequence encoder plus one endpoint state", "state_update":"within-window GRU updates; compact synchronization is setup only", "state_structure":"forward GRU state, endpoint-cell state, and fixed moment/index buffers", "frequency_representation":"no spectral transform", "temporal_schedule":"fixed pooled sequence length and selected reset-transition indices", "readout_history":"final recurrent states plus whole-window raw statistics", "temporal_readout":"dense or compact class-relative affine readout", "exit_policy":"fixed full-window classification; no early exit"}

def review_pair(before_sources: dict[str,str], after_sources: dict[str,str]):
    before_sha, after_sha = source_sha(before_sources), source_sha(after_sources)
    entry = _BY_PAIR.get((before_sha, after_sha))
    if entry is None: return None
    before_count, after_count = entry["before_transitions"], entry["after_transitions"]
    return {"classification":"preserving", "fingerprint":_fingerprint(after_count), "fingerprint_complete":True, "residual_components":[], "changed_components":[], "notes":"Exact source-pair proof for proposal %d: only the third reset-input omission transition count changes from %d to %d with dependent compact buffers, projections, selection and dispatch bounds." % (entry["proposal"],before_count,after_count), "evidence":[{"file":"train.py","line":190,"end_line":556,"code":"keptExtraForwardResetInputs, extraForwardResetTransitions, projection-bank size, covariance selection and deployment dispatch use %d entries (parent %d)." % (after_count,before_count),"kind":"complete hash-bound B03-C2 compact-reset-projection source-pair proof"}], "settings":{"proposal":entry["proposal"],"third_omission_transitions":{"before":before_count,"after":after_count},"changed_source_components":["third reset-omission transition count","dependent compact projection bank","transition index buffer","selection/synchronization/dispatch loop bounds"]}, "family_label":"MicroBiConvLSTM / compact reset-state projection deployment", "family_signature":{"sensor_pipeline":"separable temporal CNN and raw summaries","state":"per-window forward GRU plus endpoint cell","deployment":"frozen compact class-relative head and reset projections","routing":"ledger-bound third-omission transitions"}, "before_source_sha256":before_sha,"source_sha256":after_sha,"reviewer":"har-b03-c2-compact-reset-projection-exact-pairs-v1"}
